# 15. MCQ : FAMILLE, SUCCESSIONS, BIENS
# ---------------------------------------------------------------------------------------------------------------------------------
mcq(C, "di-m-famille", [
    ("Quelle est l'une des conditions fondamentales de validité du mariage ?", "Le consentement libre des deux époux",
     ["Le paiement d'un impôt de célébration", "L'accord d'un huissier de justice", "L'inscription préalable au barreau"],
     "Sans consentement libre, le mariage est exposé à la nullité.", 2),
    ("Au Cameroun, quelle autorité célèbre le mariage civil ?", "L'officier d'état civil",
     ["Le juge d'instruction", "Le procureur de la République", "Le greffier en chef"],
     "Le mariage civil est célébré devant l'officier d'état civil, qui en dresse l'acte.", 3),
    ("Quel est l'intérêt de dresser un acte de mariage ?", "Il constate le mariage et sert à en rapporter la preuve",
     ["Il fixe le montant de la dot et les conditions de la vie commune des époux", "Il remplace le contrat de travail", "Il fait obtenir la nationalité d'office"],
     "L'acte d'état civil est la preuve ordinaire du mariage.", 2),
    ("Que sanctionne la nullité d'un mariage ?", "Le défaut d'une condition de validité, comme le consentement ou la capacité",
     ["Le simple désaccord des époux sur la gestion de leur budget et de leur logement", "Le changement de domicile", "L'arrivée d'un enfant"],
     "La nullité efface le mariage en raison d'un vice à sa formation, contrairement au divorce.", 3),
    ("Quelle est la différence entre nullité du mariage et divorce ?", "La nullité sanctionne un vice originaire, le divorce rompt un mariage valable",
     ["Le divorce sanctionne un vice originaire, la nullité rompt un mariage valable", "Ils sont identiques", "La nullité n'existe qu'en droit pénal"],
     "L'un est lié à la formation du mariage, l'autre à sa dissolution.", 4),
    ("Quels sont, en droit civil de tradition française, parmi les devoirs des époux ?", "La fidélité, le secours et l'assistance",
     ["La perception des revenus de l'autre", "L'obéissance de l'un à l'autre", "L'obligation de vivre dans la même ville de naissance"],
     "Ce sont les devoirs traditionnellement énoncés par le droit civil.", 3),
    ("Qu'est-ce que le régime matrimonial légal ?", "Celui qui s'applique aux époux à défaut de contrat de mariage",
     ["Celui que le juge impose aux époux à l'occasion de leur divorce ou de leur séparation", "Celui de la séparation de biens obligatoire", "Celui d'une société commerciale"],
     "Les époux peuvent choisir un autre régime par contrat de mariage.", 3),
    ("Quelle est la conséquence du régime de la séparation de biens ?", "Chaque époux conserve la propriété et la gestion de ses biens personnels",
     ["Les biens des deux époux deviennent communs dès la célébration du mariage civil", "L'un des époux gère seul tous les biens", "Les époux n'ont plus de patrimoine"],
     "C'est l'organisation des rapports pécuniaires des époux.", 3),
    ("Sous un régime de communauté, qu'appelle-t-on un bien propre ?", "Un bien qui reste la propriété d'un seul époux",
     ["Un bien commun appartenant aux deux époux ensemble", "Un bien du domaine public", "Un bien saisi"],
     "Les biens propres sont, par exemple, ceux que l'époux possédait avant le mariage ou reçus par succession.", 4),
    ("Qu'est-ce que le contrat de mariage ?", "Une convention qui fixe le régime matrimonial des futurs époux",
     ["Un contrat de travail conclu entre époux pour la gestion d'une entreprise", "Un acte constatant le divorce", "Un acte reconnaissant un enfant"],
     "Il est généralement établi avant la célébration, avec un notaire dans les pays qui l'exigent.", 3),
    ("Dans la famille, qu'est-ce que la filiation ?", "Le lien juridique unissant l'enfant à ses parents",
     ["Le lien juridique unissant les deux époux entre eux", "Le lien juridique unissant deux frères", "Le lien de voisinage"],
     "La filiation peut être établie par la loi, la volonté ou le jugement.", 1),
    ("Comment la filiation maternelle est-elle en principe établie ?", "Par la désignation de la mère dans l'acte de naissance de l'enfant",
     ["Par un acte de décès dressé par l'officier d'état civil à la mort de la mère", "Par un jugement de divorce", "Par une quittance de loyer"],
     "La maternité est certaine : mater semper certa est.", 3),
    ("Que signifie la présomption de paternité du mari ?", "Le mari de la mère est présumé être le père de l'enfant né pendant le mariage",
     ["Le père est toujours inconnu lorsque l'enfant naît pendant le mariage de sa mère", "Le père est toujours le plus âgé", "Le père doit d'abord faire une reconnaissance"],
     "Elle est généralement susceptible de contestation dans les conditions fixées par la loi.", 4),
    ("Que permet la reconnaissance volontaire d'un enfant ?", "Établir la filiation à l'égard de celui qui reconnaît",
     ["Obtenir la nationalité de l'enfant sans aucune condition", "Divorcer sans juge", "Changer le nom du père"],
     "C'est une déclaration de volonté de s'attribuer la paternité ou la maternité.", 3),
    ("Qu'est-ce que l'adoption ?", "Un lien de filiation fondé sur la volonté et décidé par une autorité",
     ["Une naissance dans une famille, qui établit un lien de filiation par le sang", "Un mariage entre cousins", "Une tutelle d'un majeur"],
     "L'adoption crée un lien de filiation qui ne repose pas sur la naissance.", 3),
    ("Qu'est-ce que l'intérêt supérieur de l'enfant ?", "Un principe imposant de rechercher ce qui convient le mieux à l'enfant dans toute décision",
     ["Le droit du parent d'exiger l'obéissance de l'enfant en toute circonstance et sans limite", "Le plus haut impôt dû pour un enfant", "Un privilège accordé au mineur sans limite"],
     "Il est consacré par la Convention internationale des droits de l'enfant.", 3),
    ("Que comprend l'autorité parentale ?", "Un ensemble de droits et devoirs des parents : protéger, éduquer et entretenir l'enfant",
     ["Le droit d'exiger à vie les revenus de l'enfant devenu majeur et de décider de sa nationalité", "La faculté de le marier sans son consentement", "Le droit de choisir sa nationalité"],
     "L'autorité parentale est finalisée par l'intérêt de l'enfant.", 3),
    ("À quel moment prend fin, en principe, l'autorité parentale ?", "À la majorité ou à l'émancipation de l'enfant",
     ["À l'entrée de l'enfant au collège ou dans le secondaire", "À la retraite du père", "À l'entrée de l'enfant à l'école"],
     "Elle dure tant que l'enfant est mineur et non émancipé.", 3),
    ("Qu'est-ce que l'obligation alimentaire en droit de la famille ?", "L'obligation de fournir de quoi vivre à certains proches qui sont dans le besoin",
     ["L'obligation de nourrir un animal domestique et de pourvoir à ses soins vétérinaires", "Le devoir de payer les repas de ses voisins", "L'obligation de dîner en famille"],
     "Elle existe notamment entre parents et enfants, selon les conditions de la loi.", 3),
    ("Au Cameroun, comment la dot coutumière est-elle généralement perçue ?", "Comme un élément important du mariage coutumier",
     ["Comme un impôt versé à l'État lors de la célébration", "Comme un frais de notaire", "Comme une peine pénale"],
     "Dans de nombreuses coutumes, la dot scelle l'union entre deux familles.", 3),
    ("Qu'est-ce que la parenté ?", "Le lien entre personnes descendant les unes des autres ou d'un auteur commun",
     ["Le lien entre époux, qui naît de la célébration du mariage devant l'officier d'état civil", "Le lien entre un employeur et un salarié", "Le lien entre un tuteur et le juge"],
     "On distingue la parenté en ligne directe et en ligne collatérale.", 2),
    ("Quel type de parenté unit deux frères ?", "en ligne collatérale",
     ["en ligne directe", "par alliance", "par adoption nécessairement"],
     "Les frères descendent d'un auteur commun sans descendre l'un de l'autre.", 4),
    ("Quel type de parenté unit un père et sa fille ?", "en ligne directe",
     ["en ligne collatérale", "par alliance", "uniquement par le mariage"],
     "La fille descend directement de son père.", 3),
    ("Qu'est-ce que l'alliance, en matière de parenté ?", "Le lien entre un époux et les parents de son conjoint",
     ["Le lien entre deux frères issus des mêmes père et mère", "Le lien entre un parent et son enfant", "Le lien entre un tuteur et son pupille"],
     "L'alliance naît du mariage.", 3),
    ("Qu'est-ce que le conseil de famille ?", "Un organe de proches qui participe à la protection des mineurs dans la tutelle",
     ["Une juridiction pénale composée de proches chargée de juger les infractions familiales", "Une association de quartier", "Une assemblée d'actionnaires"],
     "Il contrôle certains actes importants du tuteur.", 4),
    ("Qu'est-ce que la possession d'état d'enfant ?", "Le fait de se comporter comme l'enfant d'une personne et d'être considéré comme tel",
     ["Le fait d'occuper un bien appartenant à ses parents sans titre pendant une durée prolongée", "Le fait d'être propriétaire d'un héritage", "Le fait d'être candidat à l'adoption"],
     "Elle peut jouer en matière de preuve de la filiation.", 5),
    ("Quel est le principe de l'indisponibilité de l'état des personnes ?", "On ne peut pas modifier son état civil par simple convention",
     ["On peut vendre son nom de famille à un tiers par acte notarié ou sous seing privé", "On peut changer de filiation par contrat", "On peut renoncer à sa nationalité par accord privé"],
     "L'état des personnes échappe à la volonté des particuliers, sauf dans les cas prévus par la loi.", 5),
    ("Qu'est-ce qui distingue en principe la tutelle de la curatelle ?", "La tutelle est un régime de représentation, la curatelle un régime d'assistance",
     ["La tutelle est un régime d'assistance, la curatelle un régime de représentation", "La tutelle ne concerne que les majeurs", "Elles ne présentent aucune différence"],
     "La curatelle est moins radicale que la tutelle.", 4),
], cat="Droit de la famille", src="sup-droit-intro")

mcq(C, "di-m-succ", [
    ("Quand s'ouvre une succession ?", "Au décès de la personne",
     ["À la naissance de l'héritier", "À la date de rédaction du testament", "À l'âge de la retraite"],
     "Le décès est le fait générateur de la succession.", 2),
    ("Que transmet une succession aux héritiers ?", "Le patrimoine du défunt, actif et passif",
     ["Seulement ses droits réels, à l'exclusion de ses dettes", "Seulement ses dettes", "Seulement ses droits de la personnalité"],
     "Les héritiers recueillent ses biens, mais aussi ses dettes.", 2),
    ("Qu'est-ce qu'une succession ab intestat ?", "Une succession réglée par la loi parce qu'il n'y a pas de testament",
     ["Une succession réglée par un contrat de mariage conclu entre le défunt et son conjoint", "Une succession dont le défunt est inconnu", "Une succession réservée aux étrangers"],
     "Ab intestat : sans testament.", 3),
    ("Qu'est-ce que le testament ?", "Un acte unilatéral et révocable par lequel on dispose de ses biens pour après sa mort",
     ["Un contrat irrévocable conclu avec les héritiers du vivant de la personne qui dispose", "Une décision du tribunal", "Un acte d'état civil"],
     "Il ne produit effet qu'au décès, et le testateur peut le modifier.", 2),
    ("Quelle est la différence essentielle entre donation entre vifs et testament ?", "La donation est irrévocable et immédiate, le testament révocable et effectif au décès",
     ["La donation produit effet au décès et est révocable, le testament est irrévocable et immédiat", "La donation est unilatérale, le testament conventionnel", "Il n'y a aucune différence"],
     "La donation exige l'acceptation du donataire ; le testament est un acte unilatéral.", 4),
    ("Qu'est-ce qu'un legs ?", "Une libéralité faite par testament",
     ["Une libéralité faite par contrat de mariage seulement", "Une dette du défunt", "Un impôt sur la succession"],
     "Le bénéficiaire est le légataire.", 2),
    ("En droit français, comment se caractérise un testament olographe ?", "écrit, daté et signé de la main du testateur",
     ["reçu obligatoirement par un notaire en présence de témoins", "dicté à l'huissier", "rédigé par le juge"],
     "Il se caractérise par la rédaction manuscrite du testateur.", 4),
    ("Qu'est-ce que la réserve héréditaire, dans les systèmes qui la connaissent ?", "La part de la succession que la loi garantit à certains héritiers",
     ["Une partie de la succession destinée à l'État en l'absence de testament", "Une partie réservée aux créanciers", "Une partie interdite à la vente"],
     "Elle limite la liberté du défunt de disposer par libéralités.", 5),
    ("Quelle est la portée de la quotité disponible ?", "La part dont le défunt peut librement disposer malgré les héritiers réservataires",
     ["La part que le notaire peut garder à titre de rémunération pour le partage de la succession", "La part des dettes", "La part de l'impôt"],
     "C'est la différence entre le patrimoine et la réserve.", 5),
    ("Qu'est-ce que l'acceptation d'une succession à concurrence de l'actif net ?", "L'option par laquelle l'héritier n'est tenu des dettes que dans la limite de l'actif",
     ["L'option par laquelle l'héritier renonce à la fois aux biens et aux dettes de la succession", "L'option de payer toutes les dettes de sa poche", "L'option d'hériter après dix ans"],
     "Elle protège le patrimoine personnel de l'héritier.", 5),
    ("Que veut dire renoncer à une succession ?", "Refuser d'être héritier : l'héritier est traité comme s'il ne l'avait jamais été",
     ["Accepter seulement les dettes de la succession et abandonner tous les biens aux autres", "Déléguer son héritage à l'État", "Reporter son droit à l'année suivante"],
     "L'héritier renonçant n'a droit à rien et n'est tenu d'aucune dette successorale.", 4),
    ("Quelle est la condition essentielle pour hériter ?", "Exister au moment de l'ouverture de la succession et ne pas être indigne",
     ["Être majeur et exercer la profession de commerçant à la date du décès du défunt", "Habiter la même ville que le défunt", "Avoir payé les dettes du défunt avant sa mort"],
     "Il faut exister, ou au moins être conçu, au moment du décès, et n'être pas indigne.", 4),
    ("Qu'est-ce que l'indignité successorale ?", "Une déchéance du droit de succéder pour une faute grave envers le défunt",
     ["Une peine pénale prononcée avant le décès contre l'héritier pour fraude fiscale", "Une incapacité de tous les mineurs", "Un impôt prélevé sur les héritages"],
     "Par exemple, avoir attenté à la vie du défunt.", 4),
    ("Qu'est-ce que la saisine héréditaire ?", "Le pouvoir des héritiers d'exercer, dès le décès, les droits et actions du défunt",
     ["Le pouvoir du juge de saisir les biens du défunt pour désintéresser les créanciers", "La saisie des biens par l'huissier", "Le droit des créanciers de refuser la succession"],
     "Elle évite que les droits restent sans titulaire.", 5),
    ("Que met fin à l'indivision successorale ?", "Le partage",
     ["La prescription", "Le bail", "La caution"],
     "Le partage attribue à chaque cohéritier des biens en propre.", 3),
    ("Qu'est-ce qu'un héritier réservataire ?", "Un héritier auquel la loi garantit une part minimale de la succession",
     ["Un héritier qui possède une réserve de caisse ou de trésorerie importante", "Un héritier dont le nom est inscrit au journal officiel", "Un héritier d'un parent éloigné seulement"],
     "Les descendants sont les héritiers réservataires classiques dans les systèmes qui prévoient la réserve.", 5),
    ("Quel est en principe le sort d'un pacte sur succession future, c'est-à-dire non encore ouverte ?", "prohibé, sauf exceptions prévues par la loi",
     ["toujours valable dès lors qu'un notaire en a établi l'acte", "obligatoirement notarié", "réservé à l'État"],
     "Le droit civil de tradition française interdit en principe les pactes sur succession future.", 5),
    ("Que devient la succession lorsqu'aucun héritier ne se présente ?", "Elle est dite vacante et administrée par une personne désignée",
     ["Elle est détruite par l'État qui reprend ses biens sans aucune formalité", "Elle est attribuée au premier créancier", "Elle est partagée entre les voisins"],
     "Une succession vacante est gérée par un curateur ou l'autorité compétente.", 5),
    ("Quelle différence existe entre un légataire universel et un légataire à titre particulier ?", "Le premier reçoit la totalité des biens, le second un ou plusieurs biens précis",
     ["Le premier reçoit un bien précis, le second la totalité de la succession ouverte", "Le premier est mineur, le second majeur", "Le premier est un héritier légal"],
     "Le legs à titre particulier porte sur un bien déterminé.", 4),
    ("Au Cameroun, quel est un trait général de la dévolution successorale ?", "Le droit écrit et les coutumes y coexistent selon les situations",
     ["Seul le droit coutumier s'applique à toutes les successions sans exception", "Seule la loi étrangère s'applique", "Il n'existe aucune règle de succession"],
     "La coexistence du droit écrit et du droit coutumier se retrouve en matière de famille et de succession.", 4),
], cat="Successions et libéralités", src="sup-droit-intro")

mcq(C, "di-m-biens", [
    ("Qu'est-ce qu'un bien en droit ?", "Une chose appropriable qui a une valeur économique",
     ["Une personne physique titulaire de droits et d'obligations", "Une règle de droit", "Un acte de procédure"],
     "Les biens composent le patrimoine.", 1),
    ("Quelle est la différence entre une chose et un bien ?", "La chose est un objet de la nature, le bien une chose appropriable",
     ["La chose est toujours un immeuble, le bien toujours un meuble corporel", "Le bien est toujours gratuit", "Il n'y en a aucune"],
     "Une chose devient un bien lorsqu'elle est appropriable.", 4),
    ("Quelle est la summa divisio du droit des biens ?", "La distinction entre meubles et immeubles",
     ["La distinction entre biens utiles et inutiles", "La distinction entre biens anciens et neufs", "La distinction entre biens nationaux et étrangers"],
     "Elle emporte des régimes juridiques distincts pour les meubles et les immeubles.", 3),
    ("Quelle est la qualification d'un terrain ?", "un immeuble par nature",
     ["un meuble par détermination de la loi", "un meuble incorporel", "une chose fongible"],
     "Il est fixé au sol.", 1),
    ("Quelle est la qualification d'une voiture ?", "un meuble par nature",
     ["un immeuble par nature", "un immeuble par destination", "une res nullius"],
     "Elle peut se déplacer.", 1),
    ("Quelle est la qualification d'un tracteur affecté par le propriétaire au service de son exploitation agricole ?", "un immeuble par destination",
     ["un immeuble par nature qui s'incorpore au sol", "une res nullius", "un bien du domaine public"],
     "L'affectation à l'exploitation fait un immeuble par destination.", 4),
    ("Quelle est la qualification d'une créance parmi les biens ?", "un bien meuble incorporel",
     ["un bien immeuble corporel", "un droit extrapatrimonial", "un bien hors commerce"],
     "Elle n'a pas d'existence matérielle et est un meuble par détermination de la loi.", 4),
    ("Qu'est-ce qu'une chose fongible ?", "Une chose remplaçable par une autre de même nature et quantité, comme de l'argent",
     ["Une chose d'une grande valeur affective et que rien ne peut remplacer à l'identique", "Une chose de collection", "Une chose immeuble"],
     "Exemples : somme d'argent, sacs de riz de même qualité.", 3),
    ("Quelle est la qualité d'une œuvre d'art unique au regard du remplacement des choses ?", "une chose non fongible",
     ["une chose fongible", "une chose consomptible", "une chose sans maître"],
     "On ne peut pas la remplacer par une autre.", 3),
    ("Qu'est-ce qu'une chose consomptible ?", "Une chose détruite par son premier usage, comme des aliments",
     ["Une chose qui dure toujours et ne peut être détruite par son usage", "Une chose qui doit être notariée", "Une chose qui appartient à l'État"],
     "On ne peut en faire usage sans la détruire.", 3),
    ("Que désigne l'expression « res nullius » ?", "Une chose qui n'appartient à personne et qui peut être appropriée",
     ["Une chose inaliénable du domaine public affectée à l'usage direct de tous", "Une chose volée", "Une chose indivisible"],
     "Exemple : le gibier sauvage non appartenant à autrui.", 4),
    ("Que désigne l'expression « res communes » ?", "Les choses non appropriables dont tous peuvent user, comme l'air ou l'eau courante",
     ["Les choses détenues par l'État pour l'usage exclusif de ses seuls services publics", "Les choses détenues par les époux", "Les choses appartenant à une société"],
     "Elles sont à l'usage de tous, sans pouvoir être appropriées.", 5),
    ("Quelle est la qualité du droit de propriété, selon la doctrine classique ?", "Un droit absolu, exclusif et perpétuel",
     ["Un droit relatif, partagé et temporaire", "Un droit limité à un an", "Un droit sans sanction"],
     "Ces trois caractères sont néanmoins soumis aux limites légales.", 3),
    ("Que signifie que la propriété est un droit « exclusif » ?", "Seul le propriétaire peut en principe user de la chose et s'opposer aux intrusions",
     ["Qu'elle est réservée aux commerçants et exclut tout droit pour les autres personnes physiques", "Qu'elle exclut toute limite légale", "Qu'elle est réservée à l'État"],
     "L'exclusivité empêche les tiers d'user de la chose sans l'accord du propriétaire.", 4),
    ("Que signifie que la propriété est un droit « perpétuel » ?", "Elle ne se perd pas du seul fait qu'on n'use pas de la chose",
     ["Elle est valable cent ans, après quoi le bien revient à l'État", "Elle ne peut jamais être transmise", "Elle disparaît à la mort"],
     "Elle dure tant que la chose existe et n'est pas aliénée.", 5),
    ("La propriété peut-elle être limitée par la loi ?", "Oui, notamment pour des motifs d'intérêt général ou pour protéger les droits d'autrui",
     ["Non, elle est absolue et ne peut jamais être limitée, même au nom de l'intérêt général", "Oui, mais seulement par un contrat entre voisins", "Non, sauf décision du chef de quartier"],
     "Le droit de propriété est soumis à des restrictions (urbanisme, voisinage, expropriation).", 3),
    ("Quel principe encadre l'expropriation pour cause d'utilité publique ?", "Le propriétaire reçoit une juste indemnité",
     ["Le propriétaire perd son bien sans compensation", "Le propriétaire choisit l'acquéreur", "Le propriétaire est condamné à une peine"],
     "L'expropriation suppose l'utilité publique et une indemnisation.", 3),
    ("Au Cameroun, quel document constitue la preuve définitive de la propriété d'un immeuble immatriculé ?", "Le titre foncier",
     ["Le certificat de naissance", "Le procès-verbal d'une réunion de village", "Le bulletin de salaire"],
     "L'immatriculation donne lieu à la délivrance d'un titre foncier.", 3),
    ("Qu'est-ce que l'usufruit ?", "Le droit d'user d'un bien appartenant à autrui et d'en percevoir les fruits",
     ["Le droit de disposer librement du bien d'autrui, de le vendre ou de le détruire", "Le droit de percevoir un loyer d'un locataire", "Le droit d'hériter du bien"],
     "L'usufruitier doit conserver la substance de la chose.", 3),
    ("Que doit faire l'usufruitier à la fin de l'usufruit ?", "Restituer le bien au nu-propriétaire, sans l'avoir détruit",
     ["Le vendre à un tiers de bonne foi et en conserver le prix pour lui-même", "Le détruire", "Le garder indéfiniment"],
     "Il est tenu de conserver la substance et de rendre la chose.", 4),
    ("Qu'est-ce que la nue-propriété ?", "La propriété d'un bien dont un autre a l'usufruit",
     ["La propriété d'un bien sans titre ni acte écrit qui l'établisse", "La propriété d'un bien hypothéqué", "La propriété d'un bien indivis"],
     "Le nu-propriétaire retrouve la pleine propriété à l'extinction de l'usufruit.", 4),
    ("Dans une servitude de passage, comment appelle-t-on le fonds qui subit la charge ?", "le fonds servant",
     ["le fonds dominant", "le fonds commun", "le fonds public"],
     "Le fonds qui bénéficie du passage est le fonds dominant.", 4),
    ("Dans une servitude de passage, comment appelle-t-on le fonds qui profite du passage ?", "le fonds dominant",
     ["le fonds servant", "le fonds mitoyen", "le fonds hypothécaire"],
     "La charge pèse sur le fonds servant au profit du fonds dominant.", 4),
    ("Quelle différence y a-t-il entre possession et détention ?", "Le possesseur se comporte en propriétaire, le détenteur reconnaît le droit d'un autre",
     ["Le possesseur reconnaît le droit d'un autre, le détenteur se comporte en propriétaire", "Ils sont identiques", "Il n'y a aucune différence entre les deux"],
     "Le locataire est un détenteur : il tient la chose pour le compte de son bailleur.", 4),
    ("Quels sont, dans la possession, les deux éléments classiques ?", "Le corpus (maîtrise matérielle) et l'animus (intention de se comporter en propriétaire)",
     ["La publicité et l'enregistrement de la chose auprès de l'administration foncière compétente", "Le titre et la date", "Le prix et la livraison"],
     "Le corpus est l'élément matériel, l'animus l'élément intentionnel.", 5),
    ("Qu'est-ce que la prescription acquisitive ?", "L'acquisition d'un droit par une possession prolongée pendant le temps fixé par la loi",
     ["La perte d'un droit par un non-usage prolongé pendant le temps fixé par la loi applicable", "L'acquisition d'un droit par l'effet d'un jugement", "La perte d'un droit par décision du notaire"],
     "On l'appelle aussi usucapion.", 4),
    ("À quoi sert l'action possessoire ?", "Protéger la possession d'un bien, sans trancher la question du droit de propriété",
     ["Établir définitivement qui est propriétaire en tranchant la question du droit lui-même", "Faire annuler un contrat de vente", "Faire constater un décès"],
     "L'action pétitoire, en revanche, porte sur le fond du droit de propriété.", 5),
    ("Qu'est-ce que l'accession ?", "Le droit du propriétaire d'une chose sur ce qui s'y unit ou s'y incorpore",
     ["Le droit d'accéder à une fonction publique par voie de concours national organisé", "Le droit d'acquérir la nationalité", "Le droit de visite d'un parent"],
     "Exemple : la construction édifiée sur le terrain appartient en principe au propriétaire du sol.", 5),
    ("Qu'est-ce que l'hypothèque ?", "Une sûreté réelle sur immeuble donnant au créancier un droit de suite et de préférence",
     ["Un impôt foncier prélevé chaque année sur le propriétaire d'un immeuble bâti ou non bâti", "Un droit réel d'usage d'un immeuble", "Une garantie donnée par un tiers sans lien avec le bien"],
     "Elle grève un immeuble sans que le débiteur en soit dépossédé.", 4),
    ("Qu'est-ce qu'une sûreté personnelle ?", "Une garantie qui repose sur l'engagement d'une personne, comme le cautionnement",
     ["Une garantie qui porte sur un bien précis du débiteur, comme l'hypothèque ou le gage", "Une garantie accordée par le juge", "Une garantie fiscale"],
     "La sûreté réelle porte sur un bien ; la sûreté personnelle sur un engagement personnel.", 4),
    ("Quelle différence y a-t-il entre indivision et société ?", "La société est une personne morale, l'indivision n'en est pas une",
     ["L'indivision est une personne morale distincte, la société n'en est pas une", "Chacune est une personne morale", "Ni l'une ni l'autre ne suppose plusieurs personnes"],
     "L'indivision est une situation de fait ou de droit entre plusieurs propriétaires, sans personnalité morale.", 5),
    ("Que sont les fruits d'une chose ?", "Les produits périodiques qu'elle donne sans altérer sa substance",
     ["Les dettes qu'elle génère à l'égard des tiers et de l'administration", "Les impôts qui la grèvent", "Les actes d'état civil qui l'accompagnent"],
     "Les loyers sont des fruits civils ; les récoltes des fruits naturels.", 3),
    ("Quelle est la nature d'un loyer perçu par un bailleur ?", "un fruit civil",
     ["un fruit naturel", "un produit de la chose", "une res nullius"],
     "Les fruits civils sont des revenus d'argent produits par la chose.", 4),
    ("Qu'est-ce qu'un bien du domaine public ?", "Un bien d'une personne publique affecté à l'usage du public ou à un service public",
     ["Un bien d'une société commerciale affecté à l'usage de sa clientèle ou de ses salariés", "Un bien d'un particulier", "Un bien abandonné"],
     "Le domaine public est en principe inaliénable et imprescriptible.", 4),
    ("Que signifie qu'un bien du domaine public est inaliénable ?", "Il ne peut pas être vendu tant qu'il reste affecté à l'usage public",
     ["Il ne peut jamais être utilisé par le public, même en vue de l'intérêt général", "Il peut être librement saisi", "Il appartient à un particulier"],
     "Cette protection assure l'affectation du bien à l'intérêt général.", 4),
], cat="Biens et propriété", src="sup-droit-intro")

# ---------------------------------------------------------------------------------------------------------------------------------
# 16. MCQ : ORGANISATION JUDICIAIRE ET PROCÉDURE (PRINCIPES)
# ---------------------------------------------------------------------------------------------------------------------------------
mcq(C, "dj-m-orga", [
    ("Que signifie la dualité des ordres de juridictions (judiciaire et administratif) ?", "Deux hiérarchies de juridictions : droit privé et pénal d'un côté, administration de l'autre",
     ["Deux tribunaux qui jugent chaque affaire en même temps et rendent ensuite une décision commune", "Deux juges qui siègent ensemble dans toutes les affaires", "Deux appels obligatoires dans chaque litige"],
     "Dans les systèmes dualistes, le juge administratif est séparé du juge judiciaire.", 4),
    ("Quel juge est en principe compétent pour un litige entre deux particuliers à propos d'un contrat de vente ?", "Le juge de l'ordre judiciaire",
     ["Le juge de l'ordre administratif", "Le juge constitutionnel", "Le juge des élections"],
     "Les litiges privés relèvent des juridictions judiciaires.", 2),
    ("Quel juge connaît en principe de la légalité d'une décision d'une autorité administrative ?", "Le juge administratif",
     ["Le juge d'instruction", "Le juge aux affaires familiales", "Le juge de l'exécution"],
     "Le juge administratif contrôle la légalité des actes de l'administration.", 2),
    ("Que garantit le principe d'indépendance des juges ?", "Qu'ils jugent sans recevoir d'instructions des autres pouvoirs ni des parties",
     ["Qu'ils ne sont jamais contrôlés par une juridiction supérieure, même par la voie d'un recours", "Qu'ils peuvent juger leurs propres affaires", "Qu'ils sont élus par les parties"],
     "L'indépendance est une garantie essentielle d'un procès équitable.", 3),
    ("Qu'est-ce que l'impartialité du juge ?", "L'absence de parti pris à l'égard de l'une des parties",
     ["Le droit de refuser de juger lorsque l'affaire est trop difficile", "L'obligation de siéger à plusieurs", "Le devoir de suivre l'avis du procureur"],
     "Elle se rattache à l'adage « nemo judex in causa sua ».", 3),
    ("Qu'est-ce que la collégialité ?", "La formation de jugement composée de plusieurs juges qui délibèrent ensemble",
     ["Le jugement rendu par le procureur seul après avoir entendu tous les avocats", "Le jugement rendu par le greffier", "Le jugement prononcé par l'huissier"],
     "Elle s'oppose au juge unique.", 3),
    ("Qu'est-ce que le juge unique ?", "Une formation de jugement composée d'un seul magistrat",
     ["Un juge qui ne peut jamais être récusé ni remplacé par un autre magistrat", "Un juge compétent dans tout le pays", "Un juge qui n'est pas magistrat"],
     "Certaines affaires, notamment simples ou urgentes, sont confiées à un juge unique.", 3),
    ("Que garantit le droit à un double degré de juridiction ?", "La possibilité de faire rejuger l'affaire en fait et en droit par un juge supérieur",
     ["La possibilité de choisir librement son juge parmi tous les magistrats de la juridiction", "L'obligation de consulter deux avocats", "L'interdiction de faire appel"],
     "L'appel permet un second examen du litige.", 3),
    ("Quel est le rôle d'une cour d'appel ?", "Rejuger l'affaire au fond, en fait et en droit",
     ["Contrôler seulement l'application du droit, sans rejuger les faits", "Instruire les crimes", "Dresser les actes de l'état civil"],
     "L'appel a un effet dévolutif : l'affaire est examinée à nouveau.", 3),
    ("Que fait la juridiction de cassation lorsqu'elle casse une décision ?", "Elle l'annule pour violation du droit et renvoie en principe l'affaire à une autre juridiction",
     ["Elle la confirme sans examen puis rejuge elle-même toujours l'ensemble des faits du litige en appel", "Elle rejuge elle-même toujours les faits", "Elle la suspend pour dix ans"],
     "La cassation sanctionne une mauvaise application du droit, et non l'appréciation des faits.", 4),
    ("Quelle différence y a-t-il entre appel et pourvoi en cassation ?", "L'appel rejuge les faits et le droit, le pourvoi ne contrôle que l'application du droit",
     ["L'appel ne contrôle que l'application du droit, le pourvoi rejuge les faits et le droit", "L'appel est réservé au ministère public", "Aucune différence"],
     "La cassation ne constitue pas un troisième degré de juridiction.", 4),
    ("Qu'est-ce qu'un juge du fond ?", "Un juge qui apprécie les faits et applique le droit pour trancher le litige",
     ["Un juge qui ne contrôle que la régularité de la procédure suivie, sans examiner les faits", "Un juge qui siège à la Cour suprême seulement", "Un juge chargé de la tutelle"],
     "Les juridictions de première instance et d'appel sont des juges du fond.", 4),
    ("Quelle est la différence entre voies de recours ordinaires et extraordinaires ?", "Les ordinaires sont ouvertes en principe, les extraordinaires dans des cas limités",
     ["Les ordinaires sont réservées aux crimes, les extraordinaires aux contraventions seulement", "Les extraordinaires sont toujours gratuites", "Il n'y a aucune différence"],
     "Le pourvoi en cassation et la tierce opposition sont généralement classés parmi les voies extraordinaires.", 5),
    ("Quel est en principe l'effet suspensif de l'appel ?", "Il suspend l'exécution du jugement attaqué, sauf exécution provisoire",
     ["Il accélère l'exécution du jugement attaqué et le rend immédiatement définitif", "Il annule automatiquement le jugement", "Il rend la décision définitive"],
     "L'exécution provisoire est l'exception.", 5),
    ("Que signifie l'effet dévolutif de l'appel ?", "L'affaire passe à la juridiction d'appel, qui la rejuge dans les limites de l'appel",
     ["L'affaire est transférée à l'huissier de justice qui l'exécute dans les limites de l'appel", "L'affaire est suspendue indéfiniment", "L'affaire est retirée aux parties"],
     "Le juge d'appel est saisi de l'affaire dans les limites de l'acte d'appel.", 5),
    ("Qu'est-ce que l'autorité de la chose jugée ?", "L'impossibilité de remettre en cause, entre les mêmes parties, ce qui a été jugé",
     ["L'obligation d'exécuter immédiatement tout jugement dès son prononcé, sans recours", "Le droit pour le juge de réviser tous ses jugements", "La force d'une décision non motivée"],
     "Elle évite la contrariété de décisions.", 4),
    ("Quelle différence y a-t-il entre l'autorité de la chose jugée et la force de chose jugée ?", "La première fixe la vérité entre les parties, la seconde suppose les recours épuisés",
     ["Elles sont strictement identiques et ne se distinguent que par le nom que leur donnent les auteurs", "La première vaut pour le pénal seul, la seconde pour le civil seul", "La seconde est réservée aux décisions de la Cour suprême"],
     "L'autorité est attachée dès le prononcé ; la force de chose jugée suppose l'absence ou l'épuisement des recours ordinaires.", 5),
    ("Qu'est-ce que le ministère public ?", "Le corps de magistrats qui représente la société et défend l'intérêt général",
     ["Le corps de magistrats chargé de juger toutes les affaires civiles de la juridiction", "Le syndicat des avocats", "L'ensemble des greffiers"],
     "Les magistrats du ministère public sont aussi appelés magistrats du parquet.", 2),
    ("Quelle différence y a-t-il entre magistrats du siège et du parquet ?", "Les premiers jugent, les seconds exercent l'action publique et requièrent",
     ["Les premiers plaident pour les parties, les seconds jugent les affaires civiles", "Les premiers sont des avocats", "Les seconds sont des greffiers"],
     "On parle de magistrature assise (juges) et debout (parquet).", 3),
    ("Que signifie l'unité et l'indivisibilité du ministère public ?", "Ses membres agissent au nom d'un même corps, sous l'autorité de leurs supérieurs",
     ["Chaque magistrat du parquet agit seul et sans aucun contrôle de ses supérieurs hiérarchiques", "Le parquet ne peut jamais changer de magistrat", "Le parquet n'existe que dans une juridiction"],
     "Le parquet est hiérarchisé et ses membres sont interchangeables.", 5),
    ("Qui exerce l'action publique ?", "Le ministère public, au nom de la société",
     ["Le greffier, sous l'autorité du premier président", "L'huissier", "Le notaire"],
     "L'action publique tend à l'application des peines.", 2),
    ("Quelle est la différence entre action publique et action civile ?", "La première tend à punir, la seconde à réparer le préjudice de la victime",
     ["La première tend à réparer le dommage, la seconde à punir l'auteur de l'infraction", "La première est exercée par l'huissier", "Aucune différence"],
     "L'action civile appartient à la victime ; l'action publique à la société, par le parquet.", 3),
    ("Que signifie la règle « le criminel tient le civil en l'état » ?", "Le juge civil sursoit à statuer tant que le juge pénal n'a pas jugé les mêmes faits",
     ["Le juge pénal doit surseoir à statuer tant que le juge civil n'a pas jugé les mêmes faits", "Les juges civil et pénal décident ensemble", "Le civil n'est jamais examiné"],
     "La décision pénale a autorité sur le civil pour ce qu'elle a jugé.", 5),
    ("Quelle est la mission essentielle d'un avocat ?", "Conseiller, assister et représenter ses clients en justice",
     ["Juger les affaires civiles et pénales portées devant les tribunaux", "Dresser les actes de l'état civil", "Exécuter les décisions de justice"],
     "L'avocat plaide et défend, dans le respect de la déontologie.", 1),
    ("Que protège le secret professionnel de l'avocat ?", "La confidentialité des confidences de son client",
     ["Le secret du délibéré des juges et de leurs échanges", "La confidentialité des enquêtes du parquet", "La divulgation du dossier à la presse"],
     "Le secret est une garantie des droits de la défense.", 3),
    ("Qui représente l'ordre des avocats et en préside le conseil ?", "Le bâtonnier",
     ["Le procureur général", "Le premier président", "Le greffier en chef"],
     "Le bâtonnier est élu par les avocats.", 3),
    ("Quelle est la nature de la mission du notaire ?", "Il confère l'authenticité aux actes et conseille les parties",
     ["Il tranche les litiges entre les parties et prononce la décision", "Il exerce l'action publique", "Il exécute les saisies"],
     "Le notaire est un officier public.", 2),
    ("Quel est le rôle du greffier à l'audience ?", "Assister le juge et dresser les actes qui constatent le déroulement des débats",
     ["Plaider pour l'une des parties et conclure en son nom devant la juridiction saisie", "Rendre la décision à la place du juge", "Poursuivre les infractions"],
     "Le greffier authentifie les actes de la juridiction.", 2),
    ("Qu'est-ce que la minute d'un jugement ?", "L'original de la décision, conservé au greffe",
     ["Une copie certifiée remise à la partie qui l'a demandée", "Un résumé publié dans la presse", "Un rapport du parquet"],
     "Les copies délivrées aux parties sont dites expéditions ou grosses.", 4),
    ("Qu'est-ce que la grosse d'un jugement ?", "La copie revêtue de la formule exécutoire, qui permet l'exécution forcée",
     ["L'original de la décision conservé au greffe de la juridiction qui l'a rendue", "Un simple résumé de la décision", "Une copie sans signature"],
     "La formule exécutoire autorise l'exécution forcée de la décision.", 5),
    ("Qu'est-ce qu'un titre exécutoire ?", "Un acte ou une décision permettant de recourir à l'exécution forcée",
     ["Un acte réservé aux avocats pour la préparation écrite de la défense de leurs clients", "Une quittance de loyer", "Un acte de naissance"],
     "Un jugement revêtu de la formule exécutoire en est un exemple.", 4),
    ("Que signifie la publicité des débats ?", "Les audiences sont ouvertes au public, sauf exceptions légales",
     ["Les audiences sont toujours secrètes, sauf autorisation du ministre", "Le juge fait de la publicité pour le tribunal", "Les parties sont rémunérées"],
     "Elle est une garantie d'un procès équitable.", 2),
    ("Quelle est l'obligation générale du juge concernant ses décisions ?", "Les motiver, c'est-à-dire en exposer les raisons",
     ["Les prononcer sans explication, la décision suffisant à elle seule", "Les soumettre au vote public", "Les faire valider par les parties"],
     "La motivation permet aux parties de comprendre et de contester.", 3),
    ("Que signifie l'interdiction faite au juge de se prononcer par voie de disposition générale et réglementaire ?", "Le juge tranche des cas particuliers, sans faire de règles générales",
     ["Le juge ne peut juger que les affaires publiques, jamais les affaires privées", "Le juge ne peut pas citer la loi", "Le juge ne peut pas siéger plus d'un an"],
     "C'est l'interdiction des arrêts de règlement.", 5),
    ("Quelle est la règle selon laquelle le juge ne peut refuser de juger sous prétexte du silence ou de l'obscurité de la loi ?", "L'interdiction du déni de justice",
     ["La présomption d'innocence de la personne poursuivie", "L'autorité de la chose jugée", "Le droit de suite"],
     "Le juge doit trancher les litiges qui lui sont soumis, même si la loi est silencieuse ou obscure.", 4),
    ("Qu'est-ce que la compétence d'une juridiction ?", "L'aptitude à connaître d'affaires déterminées, selon leur nature ou leur lieu",
     ["La capacité d'un juge à rendre la justice gratuitement dans toute affaire civile", "L'expérience d'un magistrat", "La liste des avocats près d'un tribunal"],
     "On distingue compétence d'attribution (matière) et compétence territoriale (lieu).", 3),
    ("Qu'est-ce que l'exception d'incompétence ?", "Un moyen soutenant que la juridiction saisie n'est pas celle qui doit juger",
     ["Un moyen par lequel le juge s'excuse de statuer en raison de sa charge de travail", "Un moyen tendant à faire annuler un témoignage", "Un moyen tendant à faire appel"],
     "Elle est soulevée avant toute défense au fond, en principe.", 5),
    ("À quoi sert la procédure de référé ?", "Obtenir vite du juge une mesure urgente ou provisoire, sans trancher le fond",
     ["Obtenir une décision définitive en appel après plusieurs années de procédure ordinaire", "Faire casser un jugement", "Faire constater un divorce"],
     "Le juge des référés statue en urgence.", 3),
    ("Que signifie qu'une décision du juge des référés est « provisoire » ?", "Elle ne tranche pas définitivement le fond du litige",
     ["Elle est valable pendant cent ans à compter de son prononcé", "Elle ne peut pas être exécutée", "Elle est rendue par le greffier"],
     "Le juge du fond peut ensuite statuer définitivement.", 5),
    ("Quelle est la compétence de principe des juridictions pénales ?", "Juger les infractions et prononcer les peines",
     ["Dresser les actes de naissance, de mariage et de décès", "Liquider les régimes matrimoniaux", "Statuer sur les marchés publics"],
     "Elles peuvent aussi statuer sur l'action civile accessoire.", 2),
    ("Dans l'ordre pénal, quels sont les trois grands types d'infractions du plus grave au moins grave, de façon générale ?", "Crime, délit, contravention",
     ["Contravention, délit, crime", "Délit, crime, contravention", "Crime, contravention, délit"],
     "La classification tripartite est classique en droit pénal de tradition française.", 2),
    ("Au Cameroun, quelle juridiction se situe au sommet de l'ordre judiciaire ?", "La Cour suprême",
     ["La cour d'appel", "Le tribunal de première instance", "La justice de paix"],
     "La Cour suprême est la plus haute juridiction de l'ordre judiciaire.", 2),
    ("Au Cameroun, comment sont organisées en principe les juridictions de droit commun ?", "En degrés : juridictions de base, cours d'appel et Cour suprême",
     ["Un seul tribunal pour tout le pays, sans degrés ni juridiction supérieure", "Uniquement des juridictions traditionnelles", "Uniquement des juridictions militaires"],
     "Les tribunaux de première instance, les cours d'appel et la Cour suprême forment la hiérarchie.", 3),
    ("Au Cameroun, qu'illustre la présence de juridictions traditionnelles ou coutumières de base ?", "la place reconnue au droit coutumier dans certaines matières",
     ["la suppression totale du droit écrit au profit de la seule coutume locale", "l'abolition de la Cour suprême", "l'application exclusive de la common law"],
     "Les juridictions traditionnelles connaissent de matières coutumières dans les limites de la loi.", 4),
    ("Qu'est-ce que la jonction de deux affaires par un juge ?", "La décision de les examiner ensemble, parce qu'elles sont liées",
     ["La décision de les renvoyer aux parties pour qu'elles les règlent seules", "La décision de les annuler", "La décision de les faire casser"],
     "Elle favorise la bonne administration de la justice.", 4),
    ("Qu'est-ce que le principe dispositif en procédure civile ?", "Les parties fixent l'objet du litige et le juge statue dans ces limites",
     ["Le juge fixe seul l'objet du litige et peut l'étendre à sa guise au-delà des demandes", "Le ministère public fixe l'objet du litige", "Le greffier fixe l'objet du litige"],
     "Le juge ne peut pas statuer sur plus que ce qui est demandé : ne eat judex ultra petita.", 5),
    ("Qu'est-ce que le principe de la contradiction ?", "Chaque partie doit pouvoir discuter les arguments et les preuves de l'autre",
     ["Chaque partie doit contredire systématiquement la position prise par le juge", "Les parties doivent être d'accord", "La procédure doit rester secrète"],
     "Il fait partie des droits de la défense et du procès équitable.", 3),
], cat="Organisation judiciaire et procédure", src="sup-droit-just")
